erp.post_material_purchase(uuid).definition:
CREATE OR REPLACE FUNCTION erp.post_material_purchase(p_purchase_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.material_purchase_headers%rowtype;
  r record;
  rr record;
  v_roll_count integer;
  v_roll_qty numeric(18,6);
  v_bad_rolls integer;
  v_total numeric(24,6):=0;
begin
  perform erp.require_internal();
  select * into h from erp.material_purchase_headers where id=p_purchase_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Purchase must be DRAFT'; end if;
  if h.supplier_id is null then raise exception 'Material purchase supplier is required'; end if;
  if h.location_id is null then raise exception 'Purchase location is required'; end if;
  if not exists(select 1 from erp.locations l where l.id=h.location_id and l.is_active=true and l.location_type='RAW_MATERIAL_WAREHOUSE') then raise exception 'Material purchase location must be an active raw-material warehouse'; end if;
  if not exists(select 1 from erp.material_purchase_items where purchase_id=h.id) then raise exception 'Material purchase has no lines'; end if;

  for r in select mpi.*,m.material_type from erp.material_purchase_items mpi join erp.materials m on m.id=mpi.material_id where mpi.purchase_id=p_purchase_id order by mpi.id loop
    select count(*),coalesce(sum(original_qty),0),count(*) filter(where material_id<>r.material_id or supplier_id is distinct from h.supplier_id)
      into v_roll_count,v_roll_qty,v_bad_rolls from erp.material_rolls where purchase_item_id=r.id;
    if r.material_type='FABRIC' then
      if v_roll_count=0 then raise exception 'Native FABRIC purchase item % must have roll records before posting',r.id; end if;
      if v_bad_rolls>0 then raise exception 'Fabric roll material/supplier does not match purchase item/header'; end if;
      if abs(v_roll_qty-r.qty)>0.000001 then raise exception 'Fabric purchase item % qty % does not equal sum of its rolls %',r.id,r.qty,v_roll_qty; end if;
    elsif v_roll_count>0 then
      raise exception 'Only FABRIC purchase items may have material rolls';
    end if;

    if v_roll_count>0 then
      for rr in select * from erp.material_rolls where purchase_item_id=r.id order by roll_number,id loop
        insert into erp.material_stock_movements(material_id,roll_id,location_id,movement_type,qty_signed,input_unit_cost,unit_cost_snapshot,source_type,source_id,physical_at,system_created_at,created_by)
        values(r.material_id,rr.id,h.location_id,'PURCHASE',rr.original_qty,r.unit_price,r.unit_price,'MATERIAL_PURCHASE_ROLL',rr.id,h.physical_at,clock_timestamp(),erp.current_app_user_id());
      end loop;
    else
      insert into erp.material_stock_movements(material_id,location_id,movement_type,qty_signed,input_unit_cost,unit_cost_snapshot,source_type,source_id,physical_at,system_created_at,created_by)
      values(r.material_id,h.location_id,'PURCHASE',r.qty,r.unit_price,r.unit_price,'MATERIAL_PURCHASE_ITEM',r.id,h.physical_at,clock_timestamp(),erp.current_app_user_id());
    end if;
    v_total:=v_total+r.line_total;
  end loop;

  for r in select distinct material_id from erp.material_purchase_items where purchase_id=p_purchase_id loop perform erp.recalculate_material_cost(r.material_id); end loop;
  if v_total>0 then
    perform erp.post_journal('MATERIAL_PURCHASE',h.id,erp._cp3_business_date(h.physical_at),'Material purchase '||h.purchase_number,jsonb_build_array(
      jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',round(v_total,2),'credit',0),
      jsonb_build_object('mapping_key','AP_SUPPLIER','debit',0,'credit',round(v_total,2))));
  end if;
  update erp.material_purchase_headers set status='POSTED' where id=p_purchase_id;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason) values('material_purchase_headers',p_purchase_id,'POST',erp.current_app_user_id(),'Purchase posted');
end;
$function$
